using AzureReactCrudFunction.Models;
using Npgsql;

namespace AzureReactCrudFunction.Data;

public sealed class ProductRepository(IConfiguration configuration, ILogger<ProductRepository> logger)
{
    private readonly string _connectionString = configuration["ConnectionStrings:Postgres"] ?? throw new InvalidOperationException("ConnectionStrings__Postgres is not configured.");
    public async Task<IReadOnlyList<Product>> GetAllAsync(CancellationToken ct) { const string sql = "SELECT id, name, description, price, created_at, updated_at FROM products ORDER BY id"; var result = new List<Product>(); await using var connection = new NpgsqlConnection(_connectionString); await connection.OpenAsync(ct); await using var command = new NpgsqlCommand(sql, connection); await using var reader = await command.ExecuteReaderAsync(ct); while (await reader.ReadAsync(ct)) result.Add(Read(reader)); return result; }
    public async Task<Product?> GetByIdAsync(int id, CancellationToken ct) { const string sql = "SELECT id, name, description, price, created_at, updated_at FROM products WHERE id = @id"; await using var connection = new NpgsqlConnection(_connectionString); await connection.OpenAsync(ct); await using var command = new NpgsqlCommand(sql, connection); command.Parameters.AddWithValue("id", id); await using var reader = await command.ExecuteReaderAsync(ct); return await reader.ReadAsync(ct) ? Read(reader) : null; }
    public async Task<Product> CreateAsync(ProductInput input, CancellationToken ct) { const string sql = "INSERT INTO products (name, description, price) VALUES (@name, @description, @price) RETURNING id, name, description, price, created_at, updated_at"; return (await ExecuteReturningAsync(sql, input, null, ct))!; }
    public async Task<Product?> UpdateAsync(int id, ProductInput input, CancellationToken ct) { const string sql = "UPDATE products SET name = @name, description = @description, price = @price, updated_at = CURRENT_TIMESTAMP WHERE id = @id RETURNING id, name, description, price, created_at, updated_at"; return await ExecuteReturningAsync(sql, input, id, ct); }
    public async Task<bool> DeleteAsync(int id, CancellationToken ct) { const string sql = "DELETE FROM products WHERE id = @id"; await using var connection = new NpgsqlConnection(_connectionString); await connection.OpenAsync(ct); await using var command = new NpgsqlCommand(sql, connection); command.Parameters.AddWithValue("id", id); return await command.ExecuteNonQueryAsync(ct) == 1; }
    private async Task<Product?> ExecuteReturningAsync(string sql, ProductInput input, int? id, CancellationToken ct) { await using var connection = new NpgsqlConnection(_connectionString); await connection.OpenAsync(ct); await using var command = new NpgsqlCommand(sql, connection); command.Parameters.AddWithValue("name", input.Name!.Trim()); command.Parameters.AddWithValue("description", string.IsNullOrWhiteSpace(input.Description) ? DBNull.Value : input.Description.Trim()); command.Parameters.AddWithValue("price", input.Price); if (id.HasValue) command.Parameters.AddWithValue("id", id.Value); await using var reader = await command.ExecuteReaderAsync(ct); return await reader.ReadAsync(ct) ? Read(reader) : null; }
    private static Product Read(NpgsqlDataReader r) => new(r.GetInt32(0), r.GetString(1), r.IsDBNull(2) ? null : r.GetString(2), r.GetDecimal(3), r.GetDateTime(4), r.GetDateTime(5));
}
